const { encodeCursor, decodeCursor } = require('./cursor');

function newestFirst(a, b) {
  return b.createdAt - a.createdAt || (a.id < b.id ? 1 : a.id > b.id ? -1 : 0);
}

function olderThan(e, c) {
  return e.createdAt < c.createdAt || (e.createdAt === c.createdAt && e.id < c.id);
}

function feedPage(events, { after, limit = 20 } = {}) {
  const sorted = [...events].sort(newestFirst);
  const rest = after ? sorted.filter((e) => olderThan(e, decodeCursor(after))) : sorted;
  const items = rest.slice(0, limit);
  return { items, next: rest.length > limit ? encodeCursor(items[items.length - 1]) : null };
}

module.exports = { feedPage };

files.src/pager.js:
// Keyset pagination over rows sorted newest first by key(row). A key is a number or an array of
// numbers and strings, compared left to right.
function compareKeys(a, b) {
  const x = [].concat(a);
  const y = [].concat(b);
  for (let i = 0; i < x.length; i++) {
    if (x[i] < y[i]) return -1;
    if (x[i] > y[i]) return 1;
  }
  return 0;
}

function keysetPage(rows, afterKey, limit, key) {
  const rest = afterKey === null || afterKey === undefined ? rows : rows.filter((r) => compareKeys(key(r), afterKey) < 0);
  const items = rest.slice(0, limit + 1);
  const more = items.length > limit;
  if (more) items.pop();
  return { items, more };
}

module.exports = { keysetPage, compareKeys };

