files.src/db/scoped.js:
const db = require('./pool');

function scoped(tenantId) {
  if (!tenantId) throw new Error('scoped() needs a tenant id');
  const where = (filters) => {
    const keys = Object.keys(filters);
    const clause = ['tenant_id = $1', ...keys.map((k, i) => k + ' = $' + (i + 2))].join(' AND ');
    return { clause, params: [tenantId, ...keys.map((k) => filters[k])] };
  };
  return {
    select(table, filters = {}) {
      const w = where(filters);
      return db.query('SELECT * FROM ' + table + ' WHERE ' + w.clause, w.params);
    },
    insert(table, row) {
      const cols = ['tenant_id', ...Object.keys(row)];
      const params = [tenantId, ...Object.values(row)];
      return db.query('INSERT INTO ' + table + ' (' + cols.join(', ') + ') VALUES (' + params.map((_, i) => '$' + (i + 1)).join(', ') + ')', params);
    },
    remove(table, filters) {
      const w = where(filters);
      return db.query('DELETE FROM ' + table + ' WHERE ' + w.clause, w.params);
    },
  };
}

module.exports = { scoped };

