const fs = require('node:fs');
const path = require('node:path');

function parse(text, file) {
  const m = /^---\n([\s\S]*?)\n---\n([\s\S]*)$/.exec(text);
  const meta = {};
  for (const line of (m ? m[1] : '').split('\n')) {
    const i = line.indexOf(':');
    if (i > 0) meta[line.slice(0, i).trim()] = line.slice(i + 1).trim();
  }
  return { file, title: meta.title, slug: meta.slug, publish_at: meta.publish_at, draft: meta.draft === 'true', body: m ? m[2] : text };
}

function loadPosts(dir) {
  return fs.readdirSync(dir).filter((f) => f.endsWith('.md')).sort().map((f) => parse(fs.readFileSync(path.join(dir, f), 'utf8'), f));
}

function isPublished(post, now = Date.now()) {
  return !post.draft && Date.parse(post.publish_at) <= now;
}

module.exports = { loadPosts, isPublished, parse };

