const { tx } = require('./db');
const outbox = require('./outbox');
const { emit } = require('./events');
const channels = require('./channels');

let next = 1;

function send(channelId, userId, text) {
  const msg = tx((t) => {
    const m = { id: 'm' + next++, channelId, userId, text, sentAt: Date.now() };
    t.messages.push(m);
    outbox.append(t, { type: 'message.created', id: m.id });
    return m;
  });
  emit(channelId, 'message', { id: msg.id, userId, text, sentAt: msg.sentAt });
  return msg;
}

function remove(channelId, id) {
  tx((t) => {
    t.messages = t.messages.filter((m) => m.id !== id);
    outbox.append(t, { type: 'message.deleted', id });
  });
  emit(channelId, 'message.deleted', { id });
}

module.exports = { send, remove };

