files.flexdate/core.py:
import re
from datetime import date


class DateParseError(ValueError):
    pass


def _ymd(m):
    return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))


def _ym(m):
    return date(int(m.group(1)), int(m.group(2)), 1)


def _dmy(m):
    return date(int(m.group(3)), int(m.group(2)), int(m.group(1)))


def _loose(m):
    raise DateParseError('ambiguous date: ' + m.group(0))


# Tried in order; the first pattern that matches wins. LOOSE stays last.
PATTERNS = [
    (re.compile(r'^(\d{4})-(\d{2})-(\d{2})$'), _ymd),
    (re.compile(r'^(\d{4})-(\d{2})$'), _ym),
    (re.compile(r'^(\d{1,2})\.(\d{1,2})\.(\d{4})$'), _dmy),
    (re.compile(r'^(.+)-(.+)$'), _loose),
]


def parse(text):
    s = text.strip()
    for pattern, build in PATTERNS:
        m = pattern.match(s)
        if m:
            try:
                return build(m)
            except DateParseError:
                raise
            except ValueError as e:
                raise DateParseError(str(e)) from None
    raise DateParseError('unrecognised date: ' + text)

