const crypto = require('node:crypto');
const store = require('./session-store');

const IDLE_MS = 2 * 3600 * 1000;
const ADMIN_MAX_MS = 12 * 3600 * 1000;

function create(user, now = Date.now()) {
  const sid = crypto.randomBytes(24).toString('hex');
  store.put(sid, { userId: user.id, role: user.role, orgId: user.orgId, createdAt: now, lastSeen: now });
  return sid;
}

function check(sid, now = Date.now()) {
  const s = store.get(sid);
  if (!s) return null;
  if (now - s.lastSeen > IDLE_MS) return null;
  if (s.role === 'admin' && now - s.createdAt > ADMIN_MAX_MS) return null;
  s.lastSeen = now;
  return s;
}

module.exports = { create, check, IDLE_MS, ADMIN_MAX_MS };

