from crm.emails import normalize_email

CONTACTS = {}


def upsert_contact(email, **fields):
    key = normalize_email(email)
    existing = CONTACTS.get(key)
    if existing:
        for k, v in fields.items():
            if v and not existing.get(k):
                existing[k] = v
        return existing, False
    contact = dict(fields, email=key, marketing_opt_in=False, consent_source=None)
    CONTACTS[key] = contact
    return contact, True


def record_consent(contact, source):
    contact['marketing_opt_in'] = True
    contact['consent_source'] = source


def emailable(contact):
    return bool(contact['marketing_opt_in'] and contact['consent_source'])

