const R_KM = 6371;
const rad = (d) => (d * Math.PI) / 180;

function haversineKm([lng1, lat1], [lng2, lat2]) {
  const a = Math.sin(rad(lat2 - lat1) / 2) ** 2 + Math.cos(rad(lat1)) * Math.cos(rad(lat2)) * Math.sin(rad(lng2 - lng1) / 2) ** 2;
  return 2 * R_KM * Math.asin(Math.sqrt(a));
}

