const MAX_LIMIT = 100;

function paginate(items, { limit = 20, offset = 0 } = {}) {
  const n = Math.min(Number(limit) || 20, MAX_LIMIT);
  const start = Number(offset) || 0;
  return { items: items.slice(start, start + n), total: items.length, limit: n, offset: start };
}

